// FONTS MODAL — categorized for mobile + recent + normalize selection
let fontsRendered = 0;
function twFontMatchesCategory(font,cat){
  const n=String(font&&font.name||'').toLowerCase();
  const id=String(font&&font.fsdMarketId||'');
  if(cat==='all')return true;
  if(cat==='handwriting')return /script|hand|signature/.test(n);
  if(cat==='cursive')return /italic|script|slant/.test(n);
  if(cat==='calligraphy')return /script|fraktur|old english|medieval/.test(n);
  if(cat==='bold')return /bold/.test(n)&&!/script/.test(n);
  if(cat==='cute')return /cute|bubble|round|heart|soft|kawaii/.test(n) || /heart|sparkle/.test(id);
  if(cat==='art')return /fraktur|old english|medieval|double struck|goth|magic|decor|frame|glitch|cursed|circled|squared|fullwidth|mirror|upside/.test(n) || !!(font&&font._fsdLocal);
  return true;
}
function twFontsForCategory(cat){
  const local=TW_FONTS.filter(f=>f&&f._fsdLocal);
  const global=TW_FONTS.filter(f=>!f._fsdLocal);
  if(cat==='recent'){
    const names=twReadJson(TW_RECENT_FONTS_KEY,[]);
    return names.map(name=>TW_FONTS.find(f=>f.name===name)).filter(Boolean);
  }
  if(cat==='popular'){
    const mixed=global.concat(local);
    return window.usPrioritizeFonts?window.usPrioritizeFonts(mixed).slice(0,36):mixed.slice(0,36);
  }
  if(cat==='all')return global.concat(local);
  return TW_FONTS.filter(f=>twFontMatchesCategory(f,cat));
}
function twMakeFontButton(font,sample){
  let preview=sample;try{preview=font.fn(sample);}catch(_){ }
  const div=document.createElement('button');div.className='tw-font-item';
  const p=document.createElement('div');p.className='tw-font-preview';p.textContent=preview;
  const n=document.createElement('div');n.className='tw-font-name';n.textContent=window.usFontLabel?window.usFontLabel(font.name):font.name;
  div.append(p,n);div.onclick=()=>{applyFont(font);fontsModal.classList.remove('open');};return div;
}
function renderFontsModal(cat=twFontCategory){
  twFontCategory=cat;
  document.querySelectorAll('[data-font-cat]').forEach(b=>b.classList.toggle('active',b.dataset.fontCat===cat));
  const range=twSavedSelection&&twSavedSelection.end>twSavedSelection.start?twSavedSelection:null;
  const source=range?editor.value.slice(range.start,range.end):editor.value.split('\n')[0].slice(0,64);
  const plain=twPlainFromAnyStyled(source);
  const sample=(plain?plain.slice(0,32):'Letras bonitas');
  const list=twFontsForCategory(cat);
  fontsGrid.innerHTML='';fontsRendered=0;
  const normal=document.createElement('button');normal.className='tw-font-item tw-font-normal';
  normal.innerHTML='<div class="tw-font-preview">Aa • Texto normal</div><div class="tw-font-name">Remover o estilo do trecho selecionado</div>';
  normal.onclick=()=>{twNormalizeSelection();fontsModal.classList.remove('open');};fontsGrid.appendChild(normal);
  if(!list.length){const empty=document.createElement('div');empty.className='tw-font-empty';empty.textContent='Nenhum estilo recente ainda.';fontsGrid.appendChild(empty);return;}
  const batch=40;
  function renderBatch(){
    const end=Math.min(fontsRendered+batch,list.length);
    for(let i=fontsRendered;i<end;i++)fontsGrid.appendChild(twMakeFontButton(list[i],sample));
    fontsRendered=end;
  }
  renderBatch();
  const body=fontsModal.querySelector('.tw-modal-body');
  body.onscroll=()=>{if(body.scrollTop+body.clientHeight>=body.scrollHeight-180&&fontsRendered<list.length)renderBatch();};
}
document.getElementById('tw-btn-fonts').onclick=()=>{twCaptureSelection();renderFontsModal(twFontCategory);fontsModal.classList.add('open');};
document.querySelectorAll('[data-font-cat]').forEach(btn=>{btn.onclick=()=>renderFontsModal(btn.dataset.fontCat);});
document.getElementById('tw-fonts-close').onclick=()=>fontsModal.classList.remove('open');
fontsModal.onclick=(e)=>{if(e.target===fontsModal)fontsModal.classList.remove('open');};

// SYMBOLS MODAL — recent symbols + cursor-safe insertion
function twInsertSymbol(icon){
  const range=twSavedSelection||{start:editor.selectionStart||0,end:editor.selectionEnd||0};
  const value=icon+' ';
  twReplaceRange(range.start,range.end,value);twRememberSymbol(icon);
  editor.selectionStart=editor.selectionEnd=range.start+value.length;twSavedSelection={start:editor.selectionStart,end:editor.selectionEnd};
  editor.focus();showToast('Inserido: '+icon);symbolsModal.classList.remove('open');
}
function renderRecentSymbols(){
  const wrap=document.getElementById('tw-recent-symbols-wrap'),grid=document.getElementById('tw-recent-symbols-grid');
  if(!wrap||!grid)return;const items=twReadJson(TW_RECENT_SYMBOLS_KEY,[]);grid.innerHTML='';
  if(!items.length){wrap.hidden=true;return;}wrap.hidden=false;
  items.forEach(icon=>{const btn=document.createElement('button');btn.className='tw-sym-btn';btn.textContent=icon;btn.onclick=()=>twInsertSymbol(icon);grid.appendChild(btn);});
}
function renderSymbols(cat){
  const icons=(cat==='all'&&typeof av3450==='function')?av3450():(BIO_CATS[cat]||BIO_CATS.all||(typeof av3450==='function'?av3450():[]));
  symbolsGrid.innerHTML='';renderRecentSymbols();
  const modalTitle=document.querySelector('#tw-symbols-modal .tw-modal-title');
  if(modalTitle)modalTitle.textContent='SÍMBOLOS • '+icons.length.toLocaleString('pt-BR')+' • TOQUE PARA INSERIR';
  let rendered=0;const batchSize=240;
  function renderBatch(){
    const end=Math.min(rendered+batchSize,icons.length);
    for(let i=rendered;i<end;i++){
      const icon=icons[i],btn=document.createElement('button');btn.className='tw-sym-btn';btn.textContent=icon;btn.onclick=()=>twInsertSymbol(icon);symbolsGrid.appendChild(btn);
    }
    rendered=end;const old=document.getElementById('tw-sym-load-more');if(old)old.remove();
    if(rendered<icons.length){const more=document.createElement('button');more.id='tw-sym-load-more';more.className='tw-btn tw-btn-yellow tw-btn-small';more.style.cssText='grid-column:1/-1;margin:12px auto;display:block;';more.textContent='Carregar mais '+Math.min(batchSize,icons.length-rendered)+' • '+rendered+'/'+icons.length;more.onclick=renderBatch;symbolsGrid.appendChild(more);}
  }
  renderBatch();
}
document.getElementById('tw-btn-symbols').onclick=()=>{try{twCaptureSelection();renderSymbols('all');symbolsModal.classList.add('open');}catch(e){console.error(e);showToast('Não foi possível abrir os símbolos');}};
document.querySelectorAll('[data-sym-cat]').forEach(btn=>{btn.onclick=()=>{document.querySelectorAll('[data-sym-cat]').forEach(b=>b.classList.remove('active'));btn.classList.add('active');renderSymbols(btn.dataset.symCat);};});
