// VOICE INPUT - integrated fix: button now has real behavior.
(function initTextWriterVoice(){
  const voiceBtn = document.getElementById('tw-btn-voice');
  const voiceStatus = document.getElementById('tw-voice-status');
  if(!voiceBtn) return;
  const SR = window.SpeechRecognition || window.webkitSpeechRecognition;
  voiceBtn.onclick = function(){
    if(!SR){ showToast('Este navegador não oferece suporte à digitação por voz'); return; }
    if(isRecording && recognition){ try{ recognition.stop(); }catch(_e){} return; }
    try{
      recognition = new SR();
      recognition.lang = 'pt-BR';
      recognition.continuous = true;
      recognition.interimResults = true;
      let finalChunk = '';
      recognition.onstart = function(){
        isRecording = true;
        voiceBtn.textContent = '⏹ Parar';
        if(voiceStatus) voiceStatus.style.display = 'inline-flex';
      };
      recognition.onresult = function(ev){
        let interim = '';
        for(let i=ev.resultIndex;i<ev.results.length;i++){
          const t = ev.results[i][0].transcript;
          if(ev.results[i].isFinal) finalChunk += t + ' ';
          else interim += t;
        }
        if(finalChunk){
          const sep = editor.value && !/\\s$/.test(editor.value) ? ' ' : '';
          editor.value += sep + finalChunk.trim();
          finalChunk = '';
          updateCounts(); autoResize(); saveDraft(); twScheduleHistory();
        }
        if(interim && voiceStatus) voiceStatus.textContent = '● ' + interim.slice(0,40);
      };
      recognition.onerror = function(ev){
        showToast(ev && ev.error === 'not-allowed' ? 'Permita o uso do microfone no navegador' : 'Não foi possível reconhecer a voz');
      };
      recognition.onend = function(){
        isRecording = false;
        voiceBtn.textContent = '🎤 Voice Typing';
        if(voiceStatus){ voiceStatus.style.display = 'none'; voiceStatus.textContent = '● Listening...'; }
      };
      recognition.start();
    }catch(e){ isRecording=false; showToast('Não foi possível acessar o microfone'); }
  };
})();

// UPLOAD
const uploadPanel = document.getElementById('tw-upload-panel');
const uploadArea = document.getElementById('tw-upload-area');
const fileInput = document.getElementById('tw-file-input');
const uploadStatus = document.getElementById('tw-upload-lib-status');
document.getElementById('tw-btn-upload').onclick = ()=>{
  uploadPanel.style.display = uploadPanel.style.display==='none' ? 'block' : 'none';
};
uploadArea.addEventListener('dragover', (e)=>{ e.preventDefault(); uploadArea.classList.add('dragover'); });
uploadArea.addEventListener('dragleave', ()=>uploadArea.classList.remove('dragover'));
uploadArea.addEventListener('drop', (e)=>{ e.preventDefault(); uploadArea.classList.remove('dragover'); const f=e.dataTransfer.files[0]; if(f) handleFile(f); });
fileInput.onchange = (e)=>{ const f=e.target.files[0]; if(f) handleFile(f); };
async function handleFile(file){
  const name = file.name.toLowerCase();
  uploadStatus.textContent = 'Carregando: '+file.name+'...';
  try{
    let text='';
    if(name.endsWith('.txt') || name.endsWith('.md')){
      text = await file.text();
    } else if(name.endsWith('.docx')){
      if(file.size > 25*1024*1024) throw new Error('O DOCX é muito grande (máximo de 25 MB)');
      text = await twReadDocxText(file);
    } else if(name.endsWith('.pdf')){
      if(file.size > 30*1024*1024) throw new Error('O PDF é muito grande (máximo de 30 MB)');
      text = await twReadPdfTextLayer(file);
    } else {
      throw new Error('Apenas TXT / MD / DOCX / PDF são aceitos');
    }
    if(!text || !text.trim()) throw new Error(name.endsWith('.pdf') ? 'Este PDF não possui uma camada de texto legível' : 'Nenhum conteúdo de texto encontrado');
    editor.value = text;
    rawText = text; lastRenderedText = '';
    updateCounts(); autoResize(); saveDraft(false); twPushHistory();
    showToast('Arquivo carregado: '+file.name);
    uploadStatus.textContent = file.name;
  }catch(err){
    console.error('File import error:',err);
    uploadStatus.textContent='Erro: '+err.message;
    showToast(err.message || 'Não foi possível ler o arquivo');
  } finally {
    try{ fileInput.value=''; }catch(_e){}
  }
}

