    offsets[id]=len;push(bytes(id+' 0 obj\n'));var o=objs[id];if(o&&o.binary){push(bytes(o.head));push(o.binary);push(bytes(o.tail+'\n'));}else push(bytes(String(o)+'\n'));push(bytes('endobj\n'));
