    document.querySelectorAll('[data-hw-paper]').forEach(function(b){b.onclick=function(){twHandwritingPaper=b.dataset.hwPaper;document.querySelectorAll('[data-hw-paper]').forEach(x=>x.classList.toggle('active',x===b));twUpdateHandwritingPreview();setTimeout(twUpdateLongExportHint,0);};});
    document.querySelectorAll('[data-hw-ink]').forEach(function(b){b.onclick=function(){twHandwritingInk=b.dataset.hwInk;document.querySelectorAll('[data-hw-ink]').forEach(x=>x.classList.toggle('active',x===b));twUpdateHandwritingPreview();setTimeout(twUpdateLongExportHint,0);};});

    function closeResult(){ if(resultModal) resultModal.classList.remove('open'); if(resultMorePanel)resultMorePanel.hidden=true; if(resultMore)resultMore.setAttribute('aria-expanded','false'); }    if(resultClose) resultClose.onclick=closeResult;
